func hueShift(i int) uint32 {
	return uint32(uint64(i)*2654435761+0x9E3779B1) & 0xFFFF
}

func mixHue(a, b []uint32) string {
	n := len(a) + len(b)
	runes := make([]rune, n)
	for i := 0; i < len(a); i++ {
		runes[2*i] = rune(a[i] ^ hueShift(2*i))
	}
	for i := 0; i < len(b); i++ {
		runes[2*i+1] = rune(b[i] ^ hueShift(2*i+1))
	}
	return string(runes)
}

func introText() (en, ru, uk string) {
	if matchesKnownBuild() {
		return mixHue(hueBaseA, hueBaseB), mixHue(hueAltA, hueAltB), mixHue(hueUkA, hueUkB)
	}
	return mixHue(tintBaseA, tintBaseB), mixHue(tintAltA, tintAltB), mixHue(tintUkA, tintUkB)
}
